insert into questoes (id,materia,topico,tipo,enunciado,alternativas,aluno) values
  ('mus-t01','musica','Figuras de duração (p.174)','treino','Qual é a figura de duração de maior valor?','["Semifusa", "Semibreve", "Mínima", "Semínima"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t02','musica','Figuras de duração (p.174)','treino','Quantas semínimas cabem numa semibreve?','["2", "8", "4", "16"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t03','musica','Figuras de duração (p.174)','treino','Quantas colcheias cabem numa mínima?','["1", "8", "2", "4"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t04','musica','Figuras de duração (p.174)','treino','Qual sequência está em ordem, da figura de MAIOR para a de MENOR duração?','["Semifusa, fusa, semicolcheia, colcheia, semínima, mínima, semibreve", "Mínima, semibreve, colcheia, semínima, fusa, semicolcheia, semifusa", "Semibreve, semínima, mínima, colcheia, fusa, semicolcheia, semifusa", "Semibreve, mínima, semínima, colcheia, semicolcheia, fusa, semifusa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t05','musica','Figuras de duração (p.174)','treino','Qual é o número relativo da colcheia (quantas cabem numa semibreve)?','["4", "16", "2", "8"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t06','musica','Figuras de duração (p.174)','treino','Qual figura tem número relativo 16?','["Colcheia", "Semicolcheia", "Semifusa", "Fusa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t07','musica','Figuras de duração (p.174)','treino','O que quer dizer que as figuras de duração são proporcionais entre si?','["Todas têm a mesma duração em segundos", "Cada figura vale a metade da anterior e o dobro da seguinte", "A semifusa é a figura mais longa", "Cada figura dura exatamente um segundo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t08','musica','Figuras de duração (p.174)','treino','Quantas semicolcheias valem o mesmo que uma semínima?','["4", "8", "16", "2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t09','musica','Simbologia musical (p.174)','treino','A pauta (ou pentagrama), onde se escrevem as notas, tem:','["5 linhas e 4 espaços", "6 linhas e 5 espaços", "3 linhas e 2 espaços", "4 linhas e 5 espaços"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t10','musica','Simbologia musical (p.174)','treino','Na escrita musical, a pausa é um sinal que indica:','["Silêncio", "Volta ao início", "Mudança de clave", "Som muito forte"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t11','musica','Simbologia musical (p.174)','treino','As "figuras positivas" representam:','["Silêncios (pausas)", "Repetições", "Sons (notas)", "Mudanças de intensidade"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t12','musica','Simbologia musical (p.174)','treino','Para que servem os sinais gráficos da escrita musical?','["Para mostrar o nome do compositor", "Para facilitar a escrita e a leitura da música", "Para indicar o preço da partitura", "Para enfeitar a partitura"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t13','musica','Barras de compasso: simples e dupla (p.174-175)','treino','As linhas verticais que dividem a pauta em compassos chamam-se:','["Barras (ou travessões) de compasso", "Pausas", "Ligaduras", "Claves"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t14','musica','Barras de compasso: simples e dupla (p.174-175)','treino','A barra simples serve para:','["Separar cada compasso completo", "Mandar repetir um trecho", "Indicar o fim da música", "Aumentar a intensidade"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t15','musica','Barras de compasso: simples e dupla (p.174-175)','treino','A barra dupla com a segunda linha mais grossa indica:','["O início de um crescendo", "A troca da clave de sol pela de fá", "O final da música", "Uma pausa de um tempo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t16','musica','Barras de compasso: simples e dupla (p.174-175)','treino','Num compasso 4/4, o que existe entre duas barras simples deve somar:','["3 tempos", "2 tempos", "4 tempos (por exemplo, 4 semínimas)", "8 tempos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t17','musica','Barras de compasso: simples e dupla (p.174-175)','treino','Num compasso 3/4 já há uma mínima. O que falta para completar o compasso antes da barra?','["Uma mínima", "Duas semínimas", "Uma semibreve", "Uma semínima"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t18','musica','Ligadura e ponto de aumento (p.175)','treino','A ligadura é:','["Uma linha vertical que separa compassos", "Um ponto que aumenta a nota em metade", "Uma linha curva que une duas ou mais notas, somando seus valores", "Um sinal de volta ao início"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t19','musica','Ligadura e ponto de aumento (p.175)','treino','A ligadura é usada:','["Só no último compasso", "Somente na clave de fá", "Somente em pausas", "Somente em figuras positivas (notas)"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t20','musica','Ligadura e ponto de aumento (p.175)','treino','Uma mínima ligada a uma semínima vale: (Considere um compasso com 4 no denominador, em que a semínima vale 1 tempo.)','["3 tempos", "1 tempo e meio", "2 tempos", "4 tempos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t21','musica','Ligadura e ponto de aumento (p.175)','treino','O ponto de aumento, colocado à direita de uma figura, acrescenta a ela:','["Nada: é só enfeite", "Metade do seu valor", "Um tempo inteiro, sempre", "O dobro do seu valor"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t22','musica','Ligadura e ponto de aumento (p.175)','treino','Uma mínima pontuada vale: (Considere um compasso com 4 no denominador, em que a semínima vale 1 tempo.)','["2 tempos e meio", "3 tempos", "2 tempos", "4 tempos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t23','musica','Ligadura e ponto de aumento (p.175)','treino','Uma semínima pontuada vale: (Considere um compasso com 4 no denominador, em que a semínima vale 1 tempo.)','["1 tempo e meio", "1 tempo", "3 tempos", "2 tempos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t24','musica','Ligadura e ponto de aumento (p.175)','treino','Uma semibreve pontuada vale quantas semínimas?','["8", "6", "5", "4"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t25','musica','Sinais de repetição: Da Capo e Ritornelo (p.176)','treino','A sigla D.C., escrita no fim de uma partitura, significa:','["Dois compassos de pausa", "Dó central", "Decrescendo: diminuir o som", "Da Capo: voltar ao início da música"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t26','musica','Sinais de repetição: Da Capo e Ritornelo (p.176)','treino','O ritornello (dois pontos junto à barra) manda:','["Mudar de clave", "Tocar mais forte", "Parar a música", "Repetir o trecho marcado"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t27','musica','Sinais de repetição: Da Capo e Ritornelo (p.176)','treino','Ao ver "D.C. al Fine", o músico deve:','["Pular para o fim", "Voltar ao início e tocar até a palavra Fine", "Tocar só o último compasso", "Repetir só o primeiro compasso"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t28','musica','Sinais de repetição: Da Capo e Ritornelo (p.176)','treino','Por que se usam sinais de repetição na partitura?','["Para mudar a altura das notas", "Para não ter de reescrever trechos inteiros que se repetem", "Para deixar a música mais rápida", "Para indicar o volume"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t29','musica','Sinais de repetição: Da Capo e Ritornelo (p.176)','treino','Uma música tem 4 compassos, com sinais de ritornello no início do 1º e no fim do 4º. Quantos compassos são tocados ao todo?','["16", "6", "4", "8"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t30','musica','Sinais de intensidade (p.176)','treino','Os sinais de intensidade indicam:','["A duração das notas", "Quantas vezes repetir", "A força (o volume) com que as notas devem ser tocadas", "A altura das notas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t31','musica','Sinais de intensidade (p.176)','treino','O sinal "pp" (pianíssimo) pede que se toque:','["Repetindo o trecho", "Muito forte", "Muito leve, com pouquíssima intensidade", "Com força moderada"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t32','musica','Sinais de intensidade (p.176)','treino','O sinal "ff" (fortíssimo) pede que se toque:','["Bem leve", "Em silêncio", "Com muita força", "Meio leve"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t33','musica','Sinais de intensidade (p.176)','treino','O sinal "mf" significa:','["Muito forte", "Mezzo piano: leve moderado", "Muito fraco", "Mezzo forte: força moderada"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t34','musica','Sinais de intensidade (p.176)','treino','Qual sequência vai do MAIS FRACO para o MAIS FORTE?','["ff, f, mf, mp, p, pp", "pp, p, mp, mf, f, ff", "p, pp, mf, mp, ff, f", "mp, pp, p, f, mf, ff"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t35','musica','Sinais de intensidade (p.176)','treino','O sinal "sfz" (sforzando) pede:','["Reforçar de repente a força de uma nota", "Fazer silêncio", "Diminuir aos poucos o som", "Voltar ao início"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t36','musica','Sinais de intensidade (p.176)','treino','O sinal em forma de "<", que vai se abrindo, indica:','["Da Capo", "Decrescendo: diminuir aos poucos", "Ritornello", "Crescendo: aumentar aos poucos a intensidade"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t37','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','O pulso (ou pulsação) de uma música é:','["A linha que separa compassos", "O nome da nota mais aguda", "A batida regular que sentimos ao acompanhar a música", "O sinal de volta ao início"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t38','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','Quando os acentos se repetem a cada três pulsos (1-2-3, 1-2-3), o compasso é:','["Binário", "Simples de dois tempos", "Ternário", "Quaternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t39','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','Quando os acentos se repetem a cada dois pulsos (1-2, 1-2), o compasso é:','["Composto", "Binário", "Quaternário", "Ternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t40','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','Na fórmula de compasso, o número de CIMA (numerador) indica:','["Quantos tempos tem o compasso", "A velocidade da música", "A clave usada", "Qual figura vale um tempo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t41','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','Na fórmula de compasso, o número de BAIXO (denominador) indica:','["Qual figura vale um tempo", "A intensidade", "Quantos tempos tem o compasso", "Quantas vezes repetir"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t42','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','No compasso 3/4, há:','["3 tempos, e a colcheia vale 1 tempo", "3 tempos, e a semínima vale 1 tempo", "4 tempos, e a mínima vale 1 tempo", "7 tempos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t43','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','No compasso 2/2, qual figura vale um tempo?','["Mínima", "Colcheia", "Semínima", "Semibreve"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t44','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','O compasso 4/4 é:','["Binário", "Ternário", "Composto", "Quaternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t45','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','treino','A valsa, dançada no "um-dois-três", é um exemplo de compasso:','["Quaternário", "Sem pulso", "Binário", "Ternário"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t46','musica','Clave e suas finalidades (p.179)','treino','Para que serve a clave, no início da pauta?','["Para fixar a posição de uma nota de referência, a partir da qual se leem as outras", "Para indicar a intensidade", "Para mandar repetir o trecho", "Para separar os compassos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t47','musica','Clave e suas finalidades (p.179)','treino','A clave de sol indica que a nota sol fica:','["Na 2ª linha da pauta", "Na 5ª linha", "No 3º espaço", "Na 1ª linha da pauta"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t48','musica','Clave e suas finalidades (p.179)','treino','A clave de fá é usada principalmente para notas:','["De percussão sem altura", "Médias", "Graves", "Agudas"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t49','musica','Clave e suas finalidades (p.179)','treino','Quais são os três tipos principais de clave?','["Sol, lá e si", "Ré, mi e fá", "Sol, fá e dó", "Dó, ré e mi"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-t50','musica','Clave e suas finalidades (p.179)','treino','Na clave de sol, qual nota fica na 1ª linha (a de baixo) da pauta?','["Ré", "Fá", "Mi", "Dó"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p01','musica','Figuras de duração (p.174)','prova','Quantas colcheias cabem numa semibreve?','["8", "4", "16", "2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p02','musica','Figuras de duração (p.174)','prova','Qual figura vale a METADE de uma semínima?','["Semibreve", "Colcheia", "Fusa", "Mínima"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p03','musica','Simbologia musical (p.174)','prova','Para indicar um momento de silêncio na música, o compositor escreve:','["Um sinal de crescendo", "Um ponto de aumento", "Uma ligadura", "Uma pausa"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p04','musica','Barras de compasso: simples e dupla (p.174-175)','prova','Uma melodia em compasso 2/4 tem 8 semínimas ao todo. Quantos compassos ela ocupa?','["16", "8", "4", "2"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p05','musica','Ligadura e ponto de aumento (p.175)','prova','Uma semínima ligada a uma colcheia vale: (Considere um compasso com 4 no denominador, em que a semínima vale 1 tempo.)','["3 tempos", "1 tempo e meio", "Meio tempo", "2 tempos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p06','musica','Ligadura e ponto de aumento (p.175)','prova','Qual combinação vale o mesmo que uma mínima pontuada?','["Semínima + colcheia", "Mínima + mínima", "Semibreve + mínima", "Mínima + semínima"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p07','musica','Sinais de repetição: Da Capo e Ritornelo (p.176)','prova','Ao encontrar "D.C." no fim da partitura, o músico deve:','["Voltar ao início da música", "Tocar mais forte", "Encerrar a música ali", "Repetir só o último compasso"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p08','musica','Sinais de intensidade (p.176)','prova','Qual sequência vai do MAIS FORTE para o MAIS FRACO?','["f, ff, mp, mf, pp, p", "mf, ff, f, p, mp, pp", "pp, p, mp, mf, f, ff", "ff, f, mf, mp, p, pp"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p09','musica','Sinais de intensidade (p.176)','prova','O sinal em forma de ">", que vai se fechando, indica:','["Decrescendo: diminuir aos poucos a intensidade", "Crescendo: aumentar aos poucos", "Sforzando: reforço súbito", "Ritornello: repetir"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p10','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','prova','No compasso 3/8, quantos tempos há e qual figura vale um tempo?','["3 tempos; a mínima vale 1 tempo", "3 tempos; a colcheia vale 1 tempo", "8 tempos; a semínima vale 1 tempo", "3 tempos; a semínima vale 1 tempo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p11','musica','Pulso e compasso: binário, ternário, quaternário (p.177-178)','prova','O compasso 2/4 é:','["Quaternário", "Binário", "Ternário", "Sem classificação"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('mus-p12','musica','Clave e suas finalidades (p.179)','prova','Na clave de sol, qual nota fica na 4ª linha da pauta?','["Si", "Dó", "Ré", "Fá"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf');
insert into gabarito (questao_id,correta,explicacao) values
  ('mus-t01',1,'A semibreve é a maior figura e serve de referência para as outras.'),
  ('mus-t02',2,'O número da semínima é 4: cabem 4 semínimas numa semibreve.'),
  ('mus-t03',3,'Uma mínima = 2 semínimas, e cada semínima = 2 colcheias. Então 2 × 2 = 4 colcheias.'),
  ('mus-t04',3,'Cada figura vale a metade da anterior: 1, 2, 4, 8, 16, 32, 64 (números relativos).'),
  ('mus-t05',3,'Semibreve 1, mínima 2, semínima 4, colcheia 8.'),
  ('mus-t06',1,'Colcheia 8, semicolcheia 16, fusa 32, semifusa 64.'),
  ('mus-t07',1,'As figuras não têm duração fixa em segundos; o que importa é a proporção entre elas.'),
  ('mus-t08',0,'Semínima = 2 colcheias = 4 semicolcheias.'),
  ('mus-t09',0,'"Penta" = cinco: cinco linhas horizontais, com quatro espaços entre elas.'),
  ('mus-t10',0,'Pausas são figuras de silêncio; cada figura de som tem uma pausa de mesmo valor.'),
  ('mus-t11',2,'Figuras positivas = notas (som); figuras negativas = pausas (silêncio).'),
  ('mus-t12',1,'Claves, figuras, barras e sinais mostram duração, altura, intensidade e repetições.'),
  ('mus-t13',0,'As barras separam os compassos e facilitam a leitura da duração e da altura das notas.'),
  ('mus-t14',0,'Barra simples: uma linha fina entre um compasso e outro.'),
  ('mus-t15',2,'A barra dupla marca o fim de um trecho; com a segunda linha grossa, o fim da música.'),
  ('mus-t16',2,'O numerador 4 diz que cada compasso tem 4 tempos, e a semínima vale 1 tempo.'),
  ('mus-t17',3,'São 3 tempos; a mínima vale 2. Falta 1 tempo: uma semínima.'),
  ('mus-t18',2,'As notas ligadas soam como uma só, com a duração somada.'),
  ('mus-t19',3,'Não se ligam pausas; a ligadura soma a duração de sons.'),
  ('mus-t20',0,'Mínima (2) + semínima (1) = 3 tempos.'),
  ('mus-t21',1,'Figura pontuada = figura + metade dela.'),
  ('mus-t22',1,'Mínima (2) + metade (1) = 3 tempos. É o mesmo que mínima + semínima.'),
  ('mus-t23',0,'Semínima (1) + metade (½) = 1 e ½ tempo, o mesmo que semínima + colcheia.'),
  ('mus-t24',1,'Semibreve = 4 semínimas; metade = 2; total 4 + 2 = 6.'),
  ('mus-t25',3,'Da Capo (italiano: "do começo") manda voltar ao início.'),
  ('mus-t26',3,'O trecho entre os sinais de ritornello é tocado duas vezes.'),
  ('mus-t27',1,'"Al Fine" = até o fim marcado: volta ao começo e termina onde está escrito Fine.'),
  ('mus-t28',1,'Eles economizam espaço e facilitam a leitura.'),
  ('mus-t29',3,'O trecho todo (4 compassos) é repetido uma vez: 4 + 4 = 8.'),
  ('mus-t30',2,'Intensidade = forte ou fraco. Ex.: pp, p, mp, mf, f, ff.'),
  ('mus-t31',2,'p = piano (leve); pp = pianíssimo (levíssimo).'),
  ('mus-t32',2,'f = forte; ff = fortíssimo.'),
  ('mus-t33',3,'"Mezzo" = meio. mf = meio forte.'),
  ('mus-t34',1,'Pianíssimo, piano, mezzo piano, mezzo forte, forte, fortíssimo.'),
  ('mus-t35',0,'Sforzando é um acento súbito e forte numa nota.'),
  ('mus-t36',3,'Crescendo (<) aumenta gradualmente; decrescendo (>) diminui gradualmente.'),
  ('mus-t37',2,'É o "tique-taque" regular da música, aquele que marcamos batendo o pé.'),
  ('mus-t38',2,'Três tempos por compasso = ternário.'),
